(7221414, 1113923, 83313, '<td valign="top">Nice approach, circuitry IS an architecture. Hope the collective doesn''t cream this too badly for the OOTB interpretation.</td>', 'Nice approach, circuitry IS an architecture. Hope the collective doesn''t cream this too badly for the OOTB interpretation.', '2014-05-28 01:19:47.000000', NULL, 1),
(7221419, 1114054, 83313, '<td valign="top">I guess the designer''s name was "Random". I like your approach and find the not-really-planned-this-way look of this building to be fascinating.</td>', 'I guess the designer''s name was "Random". I like your approach and find the not-really-planned-this-way look of this building to be fascinating.', '2014-05-28 01:22:57.000000', NULL, 1),
(7221444, 1114185, 108069, '<td valign="top">Impressively squared off and framed. Really interesting assortment of shapes and lines. Well seen.</td>', 'Impressively squared off and framed. Really interesting assortment of shapes and lines. Well seen.', '2014-05-28 02:28:11.000000', NULL, 1),
(7221447, 1114254, 108069, '<td valign="top">I demand to not know what is happening here. This is fantastic. So well seen. I particularly like the sweeping motion into the windows, as if the entire atmosphere and now nature is being sucked in. Very cool.</td>', 'I demand to not know what is happening here. This is fantastic. So well seen. I particularly like the sweeping motion into the windows, as if the entire atmosphere and now nature is being sucked in. Very cool.', '2014-05-28 02:35:56.000000', NULL, 1),
