(7222931, 1114369, 20364, '<td valign="top">Wonderful architecture and a great perspective on it. 9</td>', 'Wonderful architecture and a great perspective on it. 9', '2014-05-31 10:35:13.000000', NULL, 1),
(7222932, 1114139, 20364, '<td valign="top">Interesting framing and subject. 9</td>', 'Interesting framing and subject. 9', '2014-05-31 10:35:39.000000', NULL, 1),
(7222933, 1113486, 20364, '<td valign="top">There may be some comments about this photo not fitting the competition. But this is amazing. one of my favorites indeed. Just awesome! I gave this a 10.</td>', 'There may be some comments about this photo not fitting the competition. But this is amazing. one of my favorites indeed. Just awesome! I gave this a 10.', '2014-05-31 10:38:04.000000', NULL, 1),
(7222980, 1114180, 49078, '<td valign="top">Marina Bay Sands in Singapore?</td>', 'Marina Bay Sands in Singapore?', '2014-05-31 13:36:12.000000', NULL, 1),
(7223023, 1114154, 67258, '<td valign="top">Lovely bit of light on the wall panels - you did well to make this such a feature in minimal editing.</td>', 'Lovely bit of light on the wall panels - you did well to make this such a feature in minimal editing.', '2014-05-31 16:08:17.000000', NULL, 1),
