(7223327, 1114409, 23484, '<td valign="top">I agree, it''s hard to get a shot of that without people around. Nice job contrasting the old with the new.</td>', 'I agree, it''s hard to get a shot of that without people around. Nice job contrasting the old with the new.', '2014-06-01 16:17:16.000000', NULL, 1),
(7223328, 1114204, 23484, '<td valign="top">Excellent point of view.</td>', 'Excellent point of view.', '2014-06-01 16:17:35.000000', NULL, 1),
(7223329, 1113486, 23484, '<td valign="top">The city from my perspective. Gorgeous image.</td>', 'The city from my perspective. Gorgeous image.', '2014-06-01 16:18:13.000000', NULL, 1),
(7223626, 1113914, 97111, '<td valign="top">I imagine another perspective might have best fitted the title, enhancing the "long" adjective. Playing a bit with the aperture / speed would have also allowed for brighter colors. I find the subject interesting though.</td>', 'I imagine another perspective might have best fitted the title, enhancing the "long" adjective. Playing a bit with the aperture / speed would have also allowed for brighter colors. I find the subject interesting though.', '2014-06-02 07:54:31.000000', NULL, 1),
(7223627, 1114037, 97111, '<td valign="top">Good framing (except maybe less of the lawn may have been better) and crisp colors but I find it''s lacking some creativity to match the challenge requirements!</td>', 'Good framing (except maybe less of the lawn may have been better) and crisp colors but I find it''s lacking some creativity to match the challenge requirements!', '2014-06-02 07:57:02.000000', NULL, 1),
(7223628, 1114309, 97111, '<td valign="top">I find the geometry of this building and capture interesting. Colors lack a bit in depth (probably due to not so good weather unfortunately...)</td>', 'I find the geometry of this building and capture interesting. Colors lack a bit in depth (probably due to not so good weather unfortunately...)', '2014-06-02 07:58:55.000000', NULL, 1),
(7223629, 1114292, 97111, '<td valign="top">A difficult shot well worked out. NOt sure if lower on the stairs may have helped cut some of the light/white effect. Interesting perspective and geometry.</td>', 'A difficult shot well worked out. NOt sure if lower on the stairs may have helped cut some of the light/white effect. Interesting perspective and geometry.', '2014-06-02 08:00:10.000000', NULL, 1),
(7223630, 1113501, 97111, '<td valign="top">Great night shot. Lacks a bit of stability I find. But the creativity in architecture is definitely there.</td>', 'Great night shot. Lacks a bit of stability I find. But the creativity in architecture is definitely there.', '2014-06-02 08:01:01.000000', NULL, 1),
(7223631, 1114431, 97111, '<td valign="top">Some sharpness to add contrast (by maybe being closer to the house and avoiding the fog effect everywhere?) might have helped to make this more interesting.</td>', 'Some sharpness to add contrast (by maybe being closer to the house and avoiding the fog effect everywhere?) might have helped to make this more interesting.', '2014-06-02 08:02:04.000000', NULL, 1),
(7223632, 1113835, 97111, '<td valign="top">I find it lacks alignment. The subject is interesting and definitely creative for "architecture". The lighting makes it also disappear a bit too much into the background tree.</td>', 'I find it lacks alignment. The subject is interesting and definitely creative for "architecture". The lighting makes it also disappear a bit too much into the background tree.', '2014-06-02 08:03:47.000000', NULL, 1),
(7223633, 1114369, 97111, '<td valign="top">I like that the perspective lines are coherent even though the windows are all over the place. Good shot.</td>', 'I like that the perspective lines are coherent even though the windows are all over the place. Good shot.', '2014-06-02 08:05:11.000000', NULL, 1),
(7223634, 1114370, 97111, '<td valign="top">I am missing a bit of the "architecture" bit, centering the right post might have given more of that effect. But then I don''t know what''s next to the post. I love the texture.</td>', 'I am missing a bit of the "architecture" bit, centering the right post might have given more of that effect. But then I don''t know what''s next to the post. I love the texture.', '2014-06-02 08:06:34.000000', NULL, 1),
(7223635, 1114154, 97111, '<td valign="top">It''s a good composition. Minimal cropping may have avoided the overload of black.</td>', 'It''s a good composition. Minimal cropping may have avoided the overload of black.', '2014-06-02 08:07:46.000000', NULL, 1),
(7223636, 1113795, 97111, '<td valign="top">Really great composition, but lacks sharpness in the background (or has too much, depending on how one wants to look at it. Sharpness all across the board or a definite difference between foreground and background in depth of field may have given an even more interesting result.</td>', 'Really great composition, but lacks sharpness in the background (or has too much, depending on how one wants to look at it. Sharpness all across the board or a definite difference between foreground and background in depth of field may have given an even more interesting result.', '2014-06-02 08:10:13.000000', NULL, 1),
(7223637, 1113583, 97111, '<td valign="top">Amazing lighting and a great composition. Just a tiny bit dark.</td>', 'Amazing lighting and a great composition. Just a tiny bit dark.', '2014-06-02 08:11:49.000000', NULL, 1),
(7223638, 1113703, 97111, '<td valign="top">A good composition and perspective. Lacks a bit in sharpness of the tower.</td>', 'A good composition and perspective. Lacks a bit in sharpness of the tower.', '2014-06-02 08:14:02.000000', NULL, 1),
(7223639, 1114293, 97111, '<td valign="top">perfect horizontality of the sign and/or balcony would have made this a really great picture. I find it''s lacking some kind of anchor.</td>', 'perfect horizontality of the sign and/or balcony would have made this a really great picture. I find it''s lacking some kind of anchor.', '2014-06-02 08:16:47.000000', NULL, 1),
(7223640, 1114161, 97111, '<td valign="top">Great symmetry and extremely interesting composition. I just don''t want to know where you were standing to make that shot! :)</td>', 'Great symmetry and extremely interesting composition. I just don''t want to know where you were standing to make that shot! :)', '2014-06-02 08:17:56.000000', NULL, 1),
