(7223642, 1113923, 97111, '<td valign="top">Great idea for this challenge! Sharper or more contrasted would have made it probably more interesting in color.</td>', 'Great idea for this challenge! Sharper or more contrasted would have made it probably more interesting in color.', '2014-06-02 08:19:34.000000', NULL, 1),
(7223643, 1114273, 97111, '<td valign="top">Past and new, a classic that works. Good lines and great composition. Catching the bird gives it just the needed bit of life.</td>', 'Past and new, a classic that works. Good lines and great composition. Catching the bird gives it just the needed bit of life.', '2014-06-02 08:20:47.000000', NULL, 1),
